from datetime import datetime

# Parse dates and split by cutoff
cutoff = datetime(2022, 6, 20)

def parse_date(date_str):
    # Format: "Jan 22, 2023" or "Apr 21, 2025"
    try:
        return datetime.strptime(date_str.strip(), "%b %d, %Y")
    except:
        return None

before_cutoff = []
after_cutoff = []

for r in reviews:
    dt = parse_date(r['date'])
    r['datetime'] = dt
    if dt and dt < cutoff:
        before_cutoff.append(r)
    elif dt and dt >= cutoff:
        after_cutoff.append(r)

print(f"Before 2022-06-20: {len(before_cutoff)} reviews")
print(f"After 2022-06-20: {len(after_cutoff)} reviews")
print(f"Total: {len(before_cutoff) + len(after_cutoff)}")

# Show samples from each group
print("\n--- Before cutoff samples ---")
for r in before_cutoff[:3]:
    print(f"{r['date']}: {r['text'][:70]}...")
print("\n--- After cutoff samples ---")
for r in after_cutoff[:3]:
    print(f"{r['date']}: {r['text'][:70]}...")
